/* ============ rendering ============ */
const stage = document.getElementById('stage');
const stack = []; // open panels
 
function el(tag,cls,html){const e=document.createElement(tag);if(cls)e.className=cls;if(html!=null)e.innerHTML=html;return e;}
 
function uniCard(u){
  const b = el('button','card uni');
  b.innerHTML =
    `<img src="${u.logo}" alt="">
     <div class="label">${L(u.name)}<div class="sub">${L(u.city)}</div></div>`;
  b.onclick = () => expand(b, p => renderColleges(p,u));
  return b;
}
 
function collegeCard(c,u){
  const b = el('button','card tile');
  b.innerHTML =
    `<div class="thumb" style="background:${GRAD[c.key]}">${ICON[c.key]}</div>
     <div class="label">${L(c.name)}</div>`;
  b.onclick = () => expand(b, p => renderMajors(p,u,c));
  return b;
}
 
function majorCard(m,u,c,instant){
  const b = el('button','card major');
  b.innerHTML = `<div class="label">${L(m.name)}</div><div class="sub">${L(m.years)}</div>`;
  b.onclick = () => (instant ? expandInstant : expand)(b, p => renderMajor(p,u,c,m));
  return b;
}
 
function renderHome(){
  stage.innerHTML='';
  const g = el('div','grid unis');
  UNIS.forEach(u => g.appendChild(uniCard(u)));
  stage.appendChild(g);
}
 
function renderAllMajors(){
  stage.innerHTML='';
  COLLEGES.forEach(c => {
    const h = el('h2',null,L(c.name));
    h.style.cssText='max-width:1150px;margin:34px auto 16px;font-size:22px;font-weight:700';
    stage.appendChild(h);
    const g = el('div','grid cols2');
    c.majors.forEach(m => g.appendChild(majorCard(m,null,c)));
    stage.appendChild(g);
  });
}
 
function head(panel,title,sub,mark){
  const h = el('div','panel-head');
  const back = el('button','back',L(UI.back));
  back.onclick = () => close(panel);
  h.appendChild(back);
  if(mark){
    const m = el('img','head-logo');
    m.src = mark.logo; m.alt='';
    h.appendChild(m);
  }
  h.appendChild(el('div',null,`<h2 class="panel-title">${title}</h2>${sub?`<p class="panel-sub">${sub}</p>`:''}`));
  panel.inner.appendChild(h);
}
 
function renderColleges(panel,u){
  head(panel,L(u.name),L(UI.pickCollege),u);
  const wrap = el('div','wrap');
  const g = el('div','grid cols2');
  COLLEGES.forEach(c => g.appendChild(collegeCard(c,u)));
  wrap.appendChild(g);
  panel.inner.appendChild(wrap);
}
 
function renderMajors(panel,u,c){
  head(panel,L(c.name),u?L(u.name):L(UI.pickMajor),u);
  const wrap = el('div','wrap');
  const g = el('div','grid cols2');
  c.majors.forEach(m => g.appendChild(majorCard(m,u,c,true)));
  wrap.appendChild(g);
  panel.inner.appendChild(wrap);
}
 
function renderMajor(panel,u,c,m){
  head(panel,L(m.name),u?L(u.name):L(c.name),u);
  const d = el('div','detail');
  const list = arr => arr.map(x=>`<li>${L(x)}</li>`).join('');
  let planHTML;
  const p = m.plan ? m.plan[lang] : null;
  if(p){
    planHTML = `<div class="plan">` + p.map((courses,i)=>
      `<div class="term"><h4>${L(UI.level(i+1))}</h4><ul>${courses.map(x=>`<li>${x}</li>`).join('')}</ul></div>`
    ).join('') + `</div>`;
  } else {
    planHTML = `<p class="empty">${L(UI.noPlan)}</p>`;
  }
  d.innerHTML =
    `<h2>${L(m.name)}</h2>
     <p class="tag">${u?L(u.name)+' — ':''}${L(UI.years)}: ${L(m.years)}</p>
     <p class="about">${L(m.about)}</p>
     <div class="block"><h3>${L(UI.study)}</h3><ul>${list(m.study)}</ul></div>
     <div class="block"><h3>${L(UI.careers)}</h3><ul>${list(m.careers)}</ul></div>
     <div class="block"><h3>${L(UI.plan)}</h3>${planHTML}</div>`;
  panel.inner.appendChild(d);
}
 
/* ============ expand / close animation ============ */
/* Driven entirely by JS (Element.animate), not CSS class toggles:
   inline styles always beat a CSS class of equal element, so a
   ".full" class trying to override inline top/left/width/height
   never actually wins and the box used to just jump. Animating
   the values directly here fixes that. */
const EASE = 'cubic-bezier(.22,.72,.2,1)';
const FULL_RADIUS = '28px'; // corner radius once a panel fills the screen
const DURATION = () =>
  matchMedia('(prefers-reduced-motion: reduce)').matches ? 1 : 450;
 
function expand(sourceEl, render){
  const r = sourceEl.getBoundingClientRect();
  const startRadius = getComputedStyle(sourceEl).borderRadius || '24px';
 
  const panel = el('div','panel');
  Object.assign(panel.style,{
    top:r.top+'px', left:r.left+'px',
    width:r.width+'px', height:r.height+'px',
    borderRadius:startRadius
  });
  const inner = el('div','panel-inner');
  panel.appendChild(inner);
  panel.inner = inner;
  panel.source = sourceEl;
  panel.render = render;
  document.body.appendChild(panel);
  document.body.style.overflow='hidden';
  stack.push(panel);
  history.pushState({panel:true}, '');
 
  // leave a small margin so the panel reads as a card floating over the
  // page rather than a flush, edge-to-edge screen
  const mx = Math.max(14, window.innerWidth*0.035);
  const my = Math.max(30, window.innerHeight*0.07);
  const targetTop = my, targetLeft = mx;
  const targetW = window.innerWidth - mx*2, targetH = window.innerHeight - my*2;
 
  const anim = panel.animate([
    { top:r.top+'px', left:r.left+'px', width:r.width+'px', height:r.height+'px', borderRadius:startRadius },
    { top:targetTop+'px', left:targetLeft+'px', width:targetW+'px', height:targetH+'px', borderRadius:FULL_RADIUS }
  ], { duration:DURATION(), easing:EASE, fill:'forwards' });
 
  anim.onfinish = () => {
    // lock the final inline values so a resize/back cycle has a clean base
    Object.assign(panel.style,{top:targetTop+'px',left:targetLeft+'px',width:targetW+'px',height:targetH+'px',borderRadius:FULL_RADIUS});
    render(panel);
    panel.classList.add('ready');
  };
}
 
/* Same as expand(), but skips the grow-from-card animation entirely and
   snaps straight to the full panel. Used when a click should feel instant,
   e.g. going from a college's major list into a major's detail page. */
function expandInstant(sourceEl, render){
  const panel = el('div','panel ready');
 
  const mx = Math.max(14, window.innerWidth*0.035);
  const my = Math.max(30, window.innerHeight*0.07);
  const targetTop = my, targetLeft = mx;
  const targetW = window.innerWidth - mx*2, targetH = window.innerHeight - my*2;
 
  Object.assign(panel.style,{
    top:targetTop+'px', left:targetLeft+'px',
    width:targetW+'px', height:targetH+'px',
    borderRadius:FULL_RADIUS
  });
 
  const inner = el('div','panel-inner');
  panel.appendChild(inner);
  panel.inner = inner;
  panel.source = sourceEl;
  panel.render = render;
  document.body.appendChild(panel);
  document.body.style.overflow='hidden';
  stack.push(panel);
  history.pushState({panel:true}, '');
 
  render(panel);
}
 
/* The visible back button (and Escape) go through history.back() rather
   than closing the panel directly, so the phone/browser back button and
   the in-page back button both do the exact same thing. _close() is the
   actual shrink-and-remove animation; it only runs in response to the
   resulting popstate event. */
function close(panel){
  history.back();
}
 
function _close(panel){
  const cur = panel.getBoundingClientRect();
  const r = panel.source.getBoundingClientRect();
  const endRadius = getComputedStyle(panel.source).borderRadius || '24px';
  panel.classList.remove('ready');
 
  const anim = panel.animate([
    { top:cur.top+'px', left:cur.left+'px', width:cur.width+'px', height:cur.height+'px', borderRadius:FULL_RADIUS },
    { top:r.top+'px', left:r.left+'px', width:r.width+'px', height:r.height+'px', borderRadius:endRadius }
  ], { duration:DURATION(), easing:EASE, fill:'forwards' });
 
  anim.onfinish = () => {
    panel.remove();
    stack.pop();
    if(!stack.length) document.body.style.overflow='';
  };
}
 
window.addEventListener('popstate', () => {
  if(stack.length) _close(stack[stack.length-1]);
});
 
document.addEventListener('keydown', e=>{
  if(e.key==='Escape' && stack.length) close(stack[stack.length-1]);
});
 
/* ============ nav + language ============ */
const navUnis = document.getElementById('navUnis');
const navMajors = document.getElementById('navMajors');
const langBtn = document.getElementById('langBtn');
let view = 'unis';
 
function paintChrome(){
  document.documentElement.lang = lang;
  document.documentElement.dir = lang==='ar' ? 'rtl' : 'ltr';
  navUnis.textContent = L(UI.unis);
  navMajors.textContent = L(UI.majors);
  langBtn.textContent = lang==='ar' ? 'EN' : 'ع';
  navUnis.setAttribute('aria-current', view==='unis');
  navMajors.setAttribute('aria-current', view==='majors');
}
function paint(){
  paintChrome();
  view==='unis' ? renderHome() : renderAllMajors();
}
navUnis.onclick = ()=>{view='unis';paint();};
navMajors.onclick = ()=>{view='majors';paint();};
langBtn.onclick = ()=>{
  lang = lang==='ar' ? 'en' : 'ar';
  while(stack.length){stack.pop().remove();}
  document.body.style.overflow='';
  paint();
};
paint();
